import test from 'node:test';
import assert from 'node:assert/strict';
import {createWorkspace,mixWorkspace,ingredients,combinationKey,combinationCount,captureConcept,validateWorkspace,markdown} from './model.js';
test('locked ingredients survive a mix and original workspace is unchanged',()=>{const w=createWorkspace();w.dimensions[0].locked=true;const before=structuredClone(w);const out=mixWorkspace(w,()=>.99);assert.equal(out.workspace.dimensions[0].selectedId,w.dimensions[0].selectedId);assert.notEqual(combinationKey(out.workspace),combinationKey(w));assert.deepEqual(w,before);});
test('all locked or singleton dimensions have no alternative',()=>{const w=createWorkspace();w.dimensions.forEach(d=>d.locked=true);assert.equal(combinationCount(w,true),1);assert.equal(mixWorkspace(w).changed,false);w.dimensions[0].locked=false;w.dimensions[0].options=w.dimensions[0].options.slice(0,1);assert.equal(mixWorkspace(w).changed,false);});
test('constant random source still produces a different valid combination',()=>{const w=createWorkspace();const out=mixWorkspace(w,()=>0);assert.equal(out.changed,true);assert.notEqual(combinationKey(w),combinationKey(out.workspace));assert.ok(out.workspace.dimensions.every(d=>d.options.some(o=>o.id===d.selectedId)));});
test('captured concept preserves ingredients when workspace changes',()=>{const w=createWorkspace();const c=captureConcept(w);const original=ingredients(w);w.dimensions[0].options[0].label='Changed';assert.deepEqual(c.ingredients,original);assert.notDeepEqual(c.ingredients,ingredients(w));});
test('portable export retains user work and rejects malformed shape',()=>{const w=createWorkspace();const c=captureConcept(w);c.title='Five-minute rehearsal';c.mechanism='Use a real decision.';w.concepts.push(c);w.activeConceptId=c.id;const round=validateWorkspace(JSON.parse(JSON.stringify(w)));assert.equal(round.activeConceptId,c.id);assert.equal(round.concepts[0].mechanism,c.mechanism);assert.match(markdown(round),/Five-minute rehearsal/);assert.throws(()=>validateWorkspace({dimensions:[]}));assert.throws(()=>validateWorkspace({dimensions:[{options:[]},{options:[]}]}));});
